 "html": "<div style=\"text-align:left; color:#000; \"><DIV STYLE=\"text-align:left;\"><SPAN STYLE=\"letter-spacing:0vh;color:#000000;font-family:Arial, Helvetica, sans-serif;\"><SPAN STYLE=\"color:#04a3e1;font-size:8.37vh;font-family:'Bebas Neue Bold';\">___</SPAN></SPAN></DIV><DIV STYLE=\"text-align:left;\"><SPAN STYLE=\"letter-spacing:0vh;color:#000000;font-family:Arial, Helvetica, sans-serif;\"><SPAN STYLE=\"font-size:4.82vh;font-family:'Oswald';\"><B><I>Jelajahi Fasilitas Kampus di PNB 360\u00b0</I></B></SPAN></SPAN></DIV><DIV STYLE=\"text-align:left;\"><SPAN STYLE=\"letter-spacing:0vh;color:#000000;font-family:Arial, Helvetica, sans-serif;\"><SPAN STYLE=\"color:#04a3e1;font-size:2.41vh;font-family:'Oswald';\"><B>Fasilitas Modern untuk Generasi Vokasi Unggul</B></SPAN></SPAN></DIV><p STYLE=\"margin:0; line-height:1.01vh;\"><BR STYLE=\"letter-spacing:0vh;color:#000000;font-size:1.01vh;font-family:Arial, Helvetica, sans-serif;\"/></p><p STYLE=\"margin:0; line-height:1.01vh;\"><BR STYLE=\"letter-spacing:0vh;color:#000000;font-size:1.01vh;font-family:Arial, Helvetica, sans-serif;\"/></p><DIV STYLE=\"text-align:left;\"><SPAN STYLE=\"letter-spacing:0vh;color:#000000;font-size:1.01vh;font-family:Arial, Helvetica, sans-serif;\">Nikmati pengalaman imersif menelusuri fasilitas kebanggaan Politeknik Negeri Bali tanpa batas jarak dan waktu. Kami menghadirkan teknologi Realitas Virtual untuk memberikan gambaran nyata mengenai lingkungan belajar yang dinamis di Jimbaran. Dari laboratorium teknologi tinggi hingga ruang praktik pariwisata, semua tersedia untuk Anda jelajahi.</SPAN></DIV><p STYLE=\"margin:0; line-height:1.01vh;\"><BR STYLE=\"letter-spacing:0vh;color:#000000;font-size:1.01vh;font-family:Arial, Helvetica, sans-serif;\"/></p><DIV STYLE=\"text-align:left;\"><SPAN STYLE=\"letter-spacing:0vh;color:#000000;font-size:1.01vh;font-family:Arial, Helvetica, sans-serif;\">Dapatkan sudut pandang baru dalam melihat fasilitas pendidikan. Kami percaya bahwa lingkungan yang mendukung adalah kunci utama dalam proses pengembangan skill dan kreativitas mahasiswa.</SPAN></DIV></div>",
